const ICON_LIBRARY=[];const iconUnique=new Set();function addCatalogIcon(icon,keywords,category){if(icon.length>8||iconUnique.has(icon))return;iconUnique.add(icon);ICON_LIBRARY.push({icon,keywords,category});}
for(const [category,entries] of Object.entries(EXTRA_ICON_GROUPS))for(const entry of entries){const [icon,keywords]=entry.split('|');addCatalogIcon(icon,keywords,category);}
