for(const [icon,keywords] of [['👋','waving hand hello'],['🤚','raised back hand'],['🖐️','hand fingers'],['✋','raised hand stop'],['🖖','vulcan salute'],['👌','ok hand'],['🤌','pinched fingers'],['🤏','pinching hand'],['✌️','victory peace hand'],['🤞','crossed fingers luck'],['🫰','finger heart'],['🤟','love you gesture'],['🤘','rock horns'],['🤙','call me hand'],['👈','left finger'],['👉','right finger'],['👆','up finger'],['👇','down finger'],['☝️','index pointing up'],['👍','thumbs up good'],['👎','thumbs down'],['✊','raised fist'],['👊','fist bump'],['🤛','left fist'],['🤜','right fist'],['👏','clapping hands'],['🙌','raising hands celebration'],['👐','open hands'],['🤲','palms up together'],['🙏','folded hands prayer gratitude'],['💪','flexed biceps strength']]){addCatalogIcon(icon,keywords,'people');for(const tone of ['🏻','🏼','🏽','🏾','🏿'])addCatalogIcon(icon.replace('️','')+tone,keywords+' skin tone','people');}
