const projectFormBeforeLibrary=projectForm;projectForm=function(p){projectFormBeforeLibrary(p);const panel=$('.icon-picker-panel');if(!panel)return;panel.innerHTML='<div class="icon-library-tools"><input class="emoji-search" placeholder="Search icons: leaf, teacher, music…" aria-label="Search icons in English"><label>Nhóm<select class="icon-category">'+Object.entries(ICON_CATEGORY_LABELS).map(([key,name])=>'<option value="'+key+'">'+name+'</option>').join('')+'</select></label></div><small class="icon-result-count" role="status"></small><div class="icon-library-results"></div><small class="icon-library-footnote">Emoji Unicode · Hình hiển thị theo thiết bị của bạn.</small>';const search=panel.querySelector('.emoji-search'),category=panel.querySelector('.icon-category'),results=panel.querySelector('.icon-library-results'),count=panel.querySelector('.icon-result-count');function draw(){const terms=search.value.trim().toLowerCase().split(/\s+/).filter(Boolean),list=ICON_LIBRARY.filter(i=>(category.value==='all'||i.category===category.value)&&terms.every(t=>i.keywords.includes(t)||i.icon.includes(t)));count.textContent=list.length+' / '+ICON_LIBRARY.length+' biểu tượng';results.innerHTML=list.map(i=>'<button type="button" data-library-icon="'+i.icon+'" title="'+i.keywords+'" aria-label="'+i.keywords+'" aria-pressed="'+($('#editor-form').elements.icon.value===i.icon)+'">'+i.icon+'</button>').join('')||'<p class="empty">Không tìm thấy. Thử từ tiếng Anh khác.</p>';}search.oninput=draw;category.onchange=draw;results.onclick=e=>{const b=e.target.closest('[data-library-icon]');if(!b)return;$('#editor-form').elements.icon.value=b.dataset.libraryIcon;$('#project-icon-preview').textContent=b.dataset.libraryIcon;panel.closest('details').open=false;};draw();};
